// Four-byte reinterpretation behind a float/pointer cast (see float-pointer-bitcast)
static inline uintptr_t d2_bits_of(float fValue) { uintptr_t nBits = 0; memcpy(&nBits, &fValue, sizeof(float)); return nBits; }
static inline uintptr_t d2_bits_of(double dValue) { return d2_bits_of((float)dValue); }
static inline uintptr_t d2_bits_of(long double dValue) { return d2_bits_of((float)dValue); }
template <bool bWide> struct d2_bits_word { typedef uintptr_t type; };
template <> struct d2_bits_word<true> { typedef uint64_t type; };
template <class T> static inline typename d2_bits_word<(sizeof(T) > sizeof(uintptr_t))>::type d2_bits_of(const T& tValue) { typename d2_bits_word<(sizeof(T) > sizeof(uintptr_t))>::type nBits = 0; memcpy(&nBits, &tValue, sizeof(T) < sizeof(nBits) ? sizeof(T) : sizeof(nBits)); return nBits; }
template <class T> static inline float d2_bits_to_float(const T& tValue) { float fValue = 0.0f; memcpy(&fValue, &tValue, sizeof(T) < sizeof(float) ? sizeof(T) : sizeof(float)); return fValue; }
template <class T, class S> static inline T d2_bits_as(const S& sValue) { T tValue = T(); memcpy(&tValue, &sValue, sizeof(T) < sizeof(S) ? sizeof(T) : sizeof(S)); return tValue; }

